import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { findCommand, shimTarget, launchCommand } from './commands.js';

// Generated by npm's own cmd-shim, for a JavaScript bin and for a native one.
const JS_SHIM = [
  '@ECHO off', 'GOTO start', ':find_dp0', 'SET dp0=%~dp0', 'EXIT /b', ':start', 'SETLOCAL', 'CALL :find_dp0', '',
  'IF EXIST "%dp0%\\node.exe" (', '  SET "_prog=%dp0%\\node.exe"', ') ELSE (', '  SET "_prog=node"', '  SET PATHEXT=%PATHEXT:;.JS;=;%', ')', '',
  'endLocal & goto #_undefined_# 2>NUL || title %COMSPEC% & "%_prog%"  "%dp0%\\node_modules\\@openai\\codex\\bin\\codex.js" %*', '',
].join('\r\n');
const EXE_SHIM = [
  '@ECHO off', 'GOTO start', ':find_dp0', 'SET dp0=%~dp0', 'EXIT /b', ':start', 'SETLOCAL', 'CALL :find_dp0',
  '"%dp0%\\node_modules\\x\\bin\\claude.exe"   %*', '',
].join('\r\n');

const SHIM = 'C:\\Users\\me\\AppData\\Roaming\\npm\\codex.cmd';

function withDir(files, fn) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'underleaf-commands-'));
  try {
    for (const f of files) fs.writeFileSync(path.join(dir, f), '', { mode: 0o755 });
    return fn(dir);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

test('finds a bare command on Unix, and ignores Windows extensions there', () => {
  withDir(['tool'], (dir) => assert.equal(findCommand('tool', [dir], { win32: false }), path.join(dir, 'tool')));
  withDir(['tool.exe'], (dir) => assert.equal(findCommand('tool', [dir], { win32: false }), null));
});

test('finds .exe and .cmd commands on Windows', () => {
  withDir(['tectonic.exe'], (dir) => assert.equal(findCommand('tectonic', [dir], { win32: true }), path.join(dir, 'tectonic.exe')));
  withDir(['codex.cmd'], (dir) => assert.equal(findCommand('codex', [dir], { win32: true }), path.join(dir, 'codex.cmd')));
});

test('prefers the .exe, and skips the extensionless sh script npm leaves beside a .cmd', () => {
  withDir(['tool', 'tool.cmd', 'tool.exe'], (dir) => assert.equal(findCommand('tool', [dir], { win32: true }), path.join(dir, 'tool.exe')));
  withDir(['tool', 'tool.cmd'], (dir) => assert.equal(findCommand('tool', [dir], { win32: true }), path.join(dir, 'tool.cmd')));
});

test('an empty PATH entry does not search the current folder', () => {
  withDir(['tool'], (dir) => {
    const cwd = process.cwd();
    process.chdir(dir);
    try {
      assert.equal(findCommand('tool', ['', '/nonexistent'], { win32: false }), null);
    } finally {
      process.chdir(cwd);
    }
  });
});

test('reads the real target out of npm wrappers', () => {
  assert.equal(shimTarget(JS_SHIM), 'node_modules\\@openai\\codex\\bin\\codex.js');
  assert.equal(shimTarget(EXE_SHIM), 'node_modules\\x\\bin\\claude.exe');
  assert.equal(shimTarget('@echo off\r\nperl "%~dp0\\tool.pl" %*\r\n'), null);
  assert.equal(shimTarget('IF EXIST "%dp0%\\node.exe" (\r\n)\r\n'), null);
});

test('passes real executables straight through', () => {
  const exe = 'C:\\Users\\me\\.local\\bin\\claude.exe';
  assert.deepEqual(launchCommand(exe, ['-x'], { win32: true }), { file: exe, args: ['-x'] });
  assert.deepEqual(launchCommand('/home/me/bin/run.cmd', ['-x'], { win32: false }), { file: '/home/me/bin/run.cmd', args: ['-x'] });
});

test('starts a JavaScript wrapper with node, without going through cmd.exe', () => {
  const args = ['-c', 'developer_instructions="the main file is a&calc.tex"'];
  assert.deepEqual(launchCommand(SHIM, args, { win32: true, read: () => JS_SHIM, node: 'C:\\node\\node.exe' }), {
    file: 'C:\\node\\node.exe',
    args: ['C:\\Users\\me\\AppData\\Roaming\\npm\\node_modules\\@openai\\codex\\bin\\codex.js', ...args],
  });
});

test('starts a native wrapper target directly', () => {
  assert.deepEqual(launchCommand(SHIM, ['-x'], { win32: true, read: () => EXE_SHIM }), {
    file: 'C:\\Users\\me\\AppData\\Roaming\\npm\\node_modules\\x\\bin\\claude.exe',
    args: ['-x'],
  });
});

test('refuses a batch file it cannot see through, instead of handing it the arguments', () => {
  assert.throws(() => launchCommand(SHIM, ['-x'], { win32: true, read: () => '@echo off\r\nsomething %*\r\n' }), /codex\.cmd/);
});
